def sha256_file(path: Path) -> str:
    return sha256(path.read_bytes()).hexdigest()


def verify_osr011_contract() -> None:
    if not SOURCE_OSR011.is_file():
        raise FileNotFoundError(
            f"Actual OSR-011 module missing: {SOURCE_OSR011}"
        )

    source = SOURCE_OSR011.read_text(encoding="utf-8")
    required = (
        'ENGINE_ID = "OSR-011"',
        "verify_callable_binding_execution_authorization_activation",
        "CallableBindingExecutionAuthorizationActivation",
        "activation_hash",
        "callable_binding_execution_activation_enabled",
        "callable_binding_allowed",
        "reasoning_execution_allowed",
        "read_only",
        "qseries_execution_allowed",
        "order_creation_allowed",
        "funds_movement_allowed",
        "portfolio_mutation_allowed",
    )
    missing = [token for token in required if token not in source]
    if missing:
        raise RuntimeError(
            "Actual OSR-011 contract mismatch; missing: "
            + ", ".join(missing)
        )

    ast.parse(source, filename=str(SOURCE_OSR011))
    print(
        "[OK] Actual OSR-011 callable binding execution activation "
        "contract verified"
    )


def write_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source.lstrip(), encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] FULL REPLACEMENT: {path.resolve()}")


def append_export(path: Path, line: str) -> None:
    existing = path.read_text(encoding="utf-8") if path.exists() else ""
    if line in existing.splitlines():
        print(f"[OK] PACKAGE EXPORT PRESENT: {path.resolve()}")
        return
    if existing and not existing.endswith("\n"):
        existing += "\n"
    path.write_text(existing + line + "\n", encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] PACKAGE UPDATED: {path.resolve()}")


def main() -> int:
    print("========================================")
    print(" OSR-012 INSTALLER")
    print(" DETERMINISTIC CALLABLE BINDING")
    print(" EXECUTION ENVELOPE GATE")
    print("========================================")

    if not (ROOT / "qseries_v2").is_dir():
        raise SystemExit(
            "[ERROR] Run this installer from the kalshi-qss-bot repository root."
        )

    verify_osr011_contract()
    protected_hash = sha256_file(SOURCE_OSR011)

    write_replacement(PRODUCTION, PRODUCTION_SOURCE)
    write_replacement(TEST, TEST_SOURCE)
    append_export(
        PACKAGE_INIT,
        "from .oracle_deterministic_callable_binding_execution_envelope_gate import *",
    )

    if sha256_file(SOURCE_OSR011) != protected_hash:
        raise RuntimeError("Protected OSR-011 module changed during installation")
    print("[PASS] Protected OSR-011 module unchanged")

    completed = subprocess.run(
        [sys.executable, str(TEST)],
        cwd=str(ROOT),
        check=False,
    )
    if completed.returncode:
        raise SystemExit(completed.returncode)

    if sha256_file(SOURCE_OSR011) != protected_hash:
        raise RuntimeError("Protected OSR-011 module changed during testing")

    print("[PASS] Protected OSR-011 module unchanged after test")
    print("[PASS] OII-015 terminal freeze remains untouched")
    print("[PASS] No acquisition or analytics module modified")
    print("[PASS] No Oracle Operator module modified")
    print("[PASS] No Q Series execution module modified")
    print("[OK] OSR-012 certification test executed automatically")
    print("[DONE] OSR-012 DETERMINISTIC EXECUTION ENVELOPE GATE INSTALLED")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
